import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';

const root = path.join(process.env.USERPROFILE, '.local', 'share', 'opencode');
const db = new DatabaseSync(path.join(root, 'opencode.db'), { readOnly: true });
const rows = db
  .prepare('SELECT type, name, tbl_name, sql FROM sqlite_master ORDER BY type, name')
  .all();
for (const r of rows) {
  console.log(`--- ${r.type} | ${r.name} | tbl=${r.tbl_name}`);
  console.log(r.sql === null ? '(null sql - internal)' : r.sql);
}
console.log('=== pragmas ===');
for (const p of ['journal_mode', 'user_version', 'application_id', 'page_size', 'encoding', 'foreign_keys']) {
  console.log(p, JSON.stringify(db.prepare(`PRAGMA ${p}`).get()));
}
db.close();

import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';

const root = path.join(process.env.USERPROFILE, '.local', 'share', 'opencode');
const db = new DatabaseSync(path.join(root, 'opencode.db'), { readOnly: true });

const p = (sql, ...args) => db.prepare(sql).all(...args);

console.log('== projects ==');
console.log(JSON.stringify(p('SELECT id, worktree, vcs FROM project'), null, 1));

console.log('== sessions by project/version ==');
console.log(
  JSON.stringify(
    p(
      'SELECT project_id, version, count(*) n, sum(parent_id IS NULL) roots FROM session GROUP BY 1,2 ORDER BY 1,2',
    ),
    null,
    1,
  ),
);

const AD = '499645fc653f159a8aa17b06d0d86fb034643969';

for (const v of ['1.18.21', '1.18.22']) {
  console.log(`\n===== version ${v} =====`);
  const sess = p('SELECT id FROM session WHERE project_id = ? AND version = ? ORDER BY id', AD, v).map(
    (r) => r.id,
  );
  console.log('sessions', sess.length);
  const inList = sess.map((s) => `'${s}'`).join(',');
  const q1 = (sql) => p(sql)[0];
  console.log(
    'messages',
    q1(`SELECT count(*) n FROM message WHERE session_id IN (${inList})`).n,
    'parts',
    q1(`SELECT count(*) n FROM part WHERE session_id IN (${inList})`).n,
    'events',
    q1(`SELECT count(*) n FROM event WHERE aggregate_id IN (${inList})`).n,
    'evseq',
    q1(`SELECT count(*) n FROM event_sequence WHERE aggregate_id IN (${inList})`).n,
  );
  console.log(
    'part.data bytes',
    q1(`SELECT sum(length(CAST(data AS BLOB))) n FROM part WHERE session_id IN (${inList})`).n,
    'message.data bytes',
    q1(`SELECT sum(length(CAST(data AS BLOB))) n FROM message WHERE session_id IN (${inList})`).n,
    'event.data bytes',
    q1(`SELECT sum(length(CAST(data AS BLOB))) n FROM event WHERE aggregate_id IN (${inList})`).n,
  );
  console.log(
    'part types',
