import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';

const root = path.join(process.env.USERPROFILE, '.local', 'share', 'opencode');
const db = new DatabaseSync(path.join(root, 'opencode.db'), { readOnly: true });
const p = (sql, ...a) => db.prepare(sql).all(...a);
const AD = '499645fc653f159a8aa17b06d0d86fb034643969';

for (const v of ['1.18.21', '1.18.22']) {
  const sess = p('SELECT id FROM session WHERE project_id=? AND version=? ORDER BY id', AD, v).map(
    (r) => r.id,
  );
  const L = sess.map((s) => `'${s}'`).join(',');
  console.log(`\n===== ${v} =====`);
  console.log(
    'distinct session.directory',
    JSON.stringify(p(`SELECT DISTINCT directory FROM session WHERE id IN (${L})`)),
  );
  console.log(
    'distinct session.path',
    JSON.stringify(p(`SELECT DISTINCT path FROM session WHERE id IN (${L})`)),
  );
  console.log(
    'children whose parent is outside the set',
    JSON.stringify(
      p(`SELECT id, parent_id FROM session WHERE id IN (${L}) AND parent_id IS NOT NULL AND parent_id NOT IN (${L})`),
    ),
  );
  console.log(
    'parents whose child is outside the set',
    JSON.stringify(
      p(`SELECT id FROM session WHERE parent_id IN (${L}) AND id NOT IN (${L})`),
    ),
  );
  console.log(
    'session.permission distinct',
    JSON.stringify(p(`SELECT DISTINCT permission FROM session WHERE id IN (${L})`)),
  );
  console.log(
    'session.metadata distinct',
    JSON.stringify(p(`SELECT DISTINCT metadata FROM session WHERE id IN (${L})`)).slice(0, 400),
  );
  console.log(
    'session.share_url distinct',
    JSON.stringify(p(`SELECT DISTINCT share_url FROM session WHERE id IN (${L})`)),
  );

  // case-sensitive needle scan with GLOB over every captured text column
  const needles = [
    ['ERW', '*ERW*'],
    ['ghp_', '*ghp_*'],
    ['github_pat_', '*github_pat_*'],
    ['sk-ant-', '*sk-ant-*'],
    ['AKIA', '*AKIA*'],
    ['xox-', '*xox?-*'],
    ['projects-other', '*projects/*'],
  ];
  for (const [label, g] of needles) {
    const parts = p(`SELECT count(*) n FROM part WHERE session_id IN (${L}) AND data GLOB ?`, g)[0].n;
    const msgs = p(`SELECT count(*) n FROM message WHERE session_id IN (${L}) AND data GLOB ?`, g)[0].n;
    const evs = p(`SELECT count(*) n FROM event WHERE aggregate_id IN (${L}) AND data GLOB ?`, g)[0].n;
    const ses = p(
      `SELECT count(*) n FROM session WHERE id IN (${L}) AND (title GLOB ? OR directory GLOB ? OR slug GLOB ? OR coalesce(path,'') GLOB ? OR coalesce(metadata,'') GLOB ? OR coalesce(permission,'') GLOB ? OR coalesce(model,'') GLOB ? OR coalesce(summary_diffs,'') GLOB ? OR coalesce(revert,'') GLOB ?)`,
      g, g, g, g, g, g, g, g, g,
    )[0].n;
    console.log(`  GLOB ${label}: part=${parts} message=${msgs} event=${evs} session=${ses}`);
  }
  // which projects/<project> tokens appear
  const rowsWith = p(
    `SELECT data FROM part WHERE session_id IN (${L}) AND data GLOB '*projects*'`,
  );
  const tokens = new Map();
  const re = /projects[\\/\\\\]+([A-Za-z0-9._-]+)/g;
  for (const r of rowsWith) {
    let m;
    const s = String(r.data);
    while ((m = re.exec(s)) !== null) tokens.set(m[1], (tokens.get(m[1]) ?? 0) + 1);
  }
  console.log('  projects/<token> in part.data:', JSON.stringify([...tokens.entries()]));

  const evWith = p(`SELECT data FROM event WHERE aggregate_id IN (${L}) AND data GLOB '*projects*'`);
  const t2 = new Map();
  for (const r of evWith) {
    let m;
    const s = String(r.data);
    re.lastIndex = 0;
    while ((m = re.exec(s)) !== null) t2.set(m[1], (t2.get(m[1]) ?? 0) + 1);
  }
  console.log('  projects/<token> in event.data:', JSON.stringify([...t2.entries()]));

  console.log(
    '  NUL bytes in part.data rows:',
    p(`SELECT count(*) n FROM part WHERE session_id IN (${L}) AND instr(data, char(0)) > 0`)[0].n,
  );
}
db.close();

